function pFees(s){ return form('Sponsor Fees', 'F', [R('Acquisition Fee', inp('acqFeePct', 'pct', { s:s }), '% of price, at closing'), R('Asset Management Fee', inp('assetMgmtPct', 'pct', { s:s }), '% of effective gross income'), R('Disposition Fee', inp('dispositionFeePct', 'pct', { s:s }), '% of sale price'), isDev(s) ? R('Development Fee', inp('devFeePct', 'pct', { s:s }), '% of hard + soft') : NOTE(''), isDev(s) ? R('Construction Management Fee', inp('cmFeePct', 'pct', { s:s }), '% of hard cost') : NOTE(''), isDev(s) ? R('Guaranty Fee', inp('guarantyFeePct', 'pct', { s:s }), '% of the construction commitment') : NOTE('Development and guaranty fees apply to development deals.')]); }
