  var subStrip = '<div class="ae-subs" role="tablist">' + t.subs.map(function(a){ return '<div class="ae-sub' + (a[0] === sub ? ' on' : '') + '" role="tab" tabindex="0" onclick="bkEdSub(\'' + tab + '\',\'' + a[0] + '\')" onkeydown="if(event.key===\'Enter\')bkEdSub(\'' + tab + '\',\'' + a[0] + '\')">' + a[1] + '</div>'; }).join('') + '</div>';
