TABS.forEach(function(t){ var fn = function(){ if(typeof window.bkHasActiveDeal === 'function' && !window.bkHasActiveDeal() && typeof window.bkEmptyState === 'function') return window.bkEmptyState(t.id); return render(t.id); };
  if(typeof window.bkRegisterRenderer === 'function') window.bkRegisterRenderer(t.id, fn); else RENDERERS[t.id] = fn; });
if(!GROUPS.some(function(g){ return g.id === 'editor'; })){ var at = Math.max(0, GROUPS.findIndex(function(g){ return g.id === 'overview'; }) + 1); GROUPS.splice(at, 0, { id:'editor', label:'Property Editor', color:'#2f5f9e', sheets:TABS.map(function(t){ return t.id; }) });
  var ni = NAV_TABS.findIndex(function(t){ return t.id === 'overview'; }) + 1; NAV_TABS.splice(ni, 0, { id:'editor', label:'Property', groups:['editor'] }); }
